const sumRunReadUnits = `-- name: SumRunReadUnits :one
SELECT CAST(coalesce(sum(units - write_units), 0) AS INTEGER) FROM sync_runs
WHERE quota_date = ?
`

// The units the sync runs on quota_date spent reading.
func (q *Queries) SumRunReadUnits(ctx context.Context, quotaDate string) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumRunReadUnits, quotaDate)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const sumRunsSince = `-- name: SumRunsSince :one
SELECT
    CAST(coalesce(sum(video_reads), 0) AS INTEGER) AS video_reads,
    CAST(coalesce(sum(probe_misses), 0) AS INTEGER) AS probe_misses
FROM sync_runs
WHERE finished_ts > ?1
`

type SumRunsSinceRow struct {
	VideoReads  int64
	ProbeMisses int64
}

// The tracklist reads and the probe misses of the runs that finished after
// since.
func (q *Queries) SumRunsSince(ctx context.Context, since string) (SumRunsSinceRow, error) {
	row := q.db.QueryRowContext(ctx, sumRunsSince, since)
	var i SumRunsSinceRow
	err := row.Scan(&i.VideoReads, &i.ProbeMisses)
	return i, err
}

const sumWriteUnits = `-- name: SumWriteUnits :one
SELECT
    CAST(coalesce(sum(units), 0) AS INTEGER) AS units,
    CAST(coalesce(sum(CASE WHEN outcome = 'pending' THEN 1 ELSE 0 END), 0) AS INTEGER) AS pending
FROM youtube_writes
WHERE quota_date = ?
`

type SumWriteUnitsRow struct {
	Units   int64
	Pending int64
}

// The units the writes sent on quota_date cost, and how many of them have not
// settled, whose cost is not yet recorded.
func (q *Queries) SumWriteUnits(ctx context.Context, quotaDate string) (SumWriteUnitsRow, error) {
	row := q.db.QueryRowContext(ctx, sumWriteUnits, quotaDate)
	var i SumWriteUnitsRow
	err := row.Scan(&i.Units, &i.Pending)
	return i, err
}

const updatePlaylistDetails = `-- name: UpdatePlaylistDetails :execrows
UPDATE playlists SET
    title = ?1,
    description = ?2
WHERE playlist_id = ?3
`

type UpdatePlaylistDetailsParams struct {
	Title       string
	Description string
	PlaylistID  string
}

// Sets a stored playlist's title and description, and changes nothing when no
// playlist has the id.
func (q *Queries) UpdatePlaylistDetails(ctx context.Context, arg UpdatePlaylistDetailsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updatePlaylistDetails, arg.Title, arg.Description, arg.PlaylistID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

